-- A group identifier is local to a turn; joining by it alone can duplicate a claim context.
create or replace function public.tipshift_claim_open(p_capability_hash bytea) returns jsonb language sql set search_path=pg_catalog,tipshift_private as $$ select jsonb_build_object('turnRef',c.turn_ref,'groupRef',c.group_ref,'groupShareBps',g.share_bps,'recipientSlot',c.recipient_slot,'shareWeight',c.share_weight,'state',c.state,'expiresAt',c.expires_at) from tipshift_private.claim_capabilities c join tipshift_private.turns t on t.turn_ref=c.turn_ref join tipshift_private.turn_groups g on g.turn_ref=c.turn_ref and g.group_ref=c.group_ref where c.capability_hash=p_capability_hash and c.expires_at>timezone('utc',now()) and t.state in ('draft','claiming','collecting') limit 1; $$;
create or replace function public.tipshift_claim_challenge(p_capability_hash bytea) returns jsonb language sql set search_path=pg_catalog,tipshift_private as $$ select jsonb_build_object('turnRef',c.turn_ref,'groupRef',c.group_ref,'groupShareBps',g.share_bps,'recipientSlot',c.recipient_slot,'shareWeight',c.share_weight,'expiresAt',c.expires_at,'challengeNonce',encode(c.challenge_nonce,'base64')) from tipshift_private.claim_capabilities c join tipshift_private.turns t on t.turn_ref=c.turn_ref join tipshift_private.turn_groups g on g.turn_ref=c.turn_ref and g.group_ref=c.group_ref where c.capability_hash=p_capability_hash and c.state='pending' and c.challenge_nonce is not null and c.challenge_expires_at>timezone('utc',now()) and c.expires_at>timezone('utc',now()) and t.state='claiming' limit 1; $$;
create or replace function public.tipshift_claim_start(p_capability_hash bytea,p_challenge_nonce bytea) returns jsonb language plpgsql set search_path=pg_catalog,tipshift_private as $$ declare updated tipshift_private.claim_capabilities%rowtype; begin if octet_length(p_capability_hash)<>32 or octet_length(p_challenge_nonce)<>32 then return null; end if; update tipshift_private.claim_capabilities c set challenge_nonce=p_challenge_nonce,challenge_expires_at=timezone('utc',now())+interval '5 minutes' from tipshift_private.turns t where c.capability_hash=p_capability_hash and c.turn_ref=t.turn_ref and c.state='pending' and c.expires_at>timezone('utc',now()) and t.state='claiming' returning c.* into updated; if not found then return null; end if; return jsonb_build_object('turnRef',updated.turn_ref,'groupRef',updated.group_ref,'groupShareBps',(select g.share_bps from tipshift_private.turn_groups g where g.turn_ref=updated.turn_ref and g.group_ref=updated.group_ref),'recipientSlot',updated.recipient_slot,'shareWeight',updated.share_weight,'expiresAt',updated.expires_at,'challengeExpiresAt',updated.challenge_expires_at); end; $$;
create or replace function public.tipshift_claim_complete(p_capability_hash bytea,p_challenge_nonce bytea,p_wallet_commitment bytea,p_wallet_ciphertext bytea) returns jsonb language plpgsql set search_path=pg_catalog,tipshift_private as $$ declare updated tipshift_private.claim_capabilities%rowtype; begin if octet_length(p_capability_hash)<>32 or octet_length(p_challenge_nonce)<>32 or octet_length(p_wallet_commitment)<>32 or octet_length(p_wallet_ciphertext)<29 then return null; end if; update tipshift_private.claim_capabilities c set state='claimed',wallet_commitment=p_wallet_commitment,wallet_ciphertext=p_wallet_ciphertext,wallet_ciphertext_version=1,claimed_at=timezone('utc',now()),challenge_nonce=null,challenge_expires_at=null,retention_delete_after=least(timezone('utc',now())+interval '31 days',c.created_at+interval '31 days') from tipshift_private.turns t where c.capability_hash=p_capability_hash and c.turn_ref=t.turn_ref and c.state='pending' and c.challenge_nonce=p_challenge_nonce and c.challenge_expires_at>timezone('utc',now()) and c.expires_at>timezone('utc',now()) and t.state='claiming' returning c.* into updated; if not found then return null; end if; return jsonb_build_object('turnRef',updated.turn_ref,'groupRef',updated.group_ref,'groupShareBps',(select g.share_bps from tipshift_private.turn_groups g where g.turn_ref=updated.turn_ref and g.group_ref=updated.group_ref),'recipientSlot',updated.recipient_slot,'shareWeight',updated.share_weight,'state',updated.state,'expiresAt',updated.expires_at); exception when unique_violation then return null; end; $$;
